const settings = $('Load Global Settings').first()?.json ?? {};
const request = $('Preview Member List Email Webhook').first()?.json ?? $input.first()?.json ?? {};
const query = request.query ?? request;
const headers = request.headers ?? {};
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const truthy = (value) => ['1', 'true', 'yes', 'y', 'on'].includes(clean(value).toLowerCase());
const deriveBaseUrl = (sourceHeaders, fallback) => {
  const forwardedProto = clean(sourceHeaders['x-forwarded-proto']);
  const forwardedHost = clean(sourceHeaders['x-forwarded-host']);
  const host = forwardedHost || clean(sourceHeaders.host);
  const forwardedPort = clean(sourceHeaders['x-forwarded-port']);
  if (!host) return fallback;
  const proto = forwardedProto || 'http';
  let authority = host;
  if (forwardedPort && !authority.includes(':')) {
    const isDefaultPort = (proto === 'http' && forwardedPort === '80') || (proto === 'https' && forwardedPort === '443');
    if (!isDefaultPort) authority = authority + ':' + forwardedPort;
  }
  return proto + '://' + authority;
};
const listOptions = {"non_renewed_members": {"label": "Members Who Have Not Renewed This Year", "description": "People who were members last season and do not currently appear in this season's paid membership package set."}, "current_members": {"label": "Current Members", "description": "Current-season paid members with a resolved email address."}, "contacts_without_current_membership": {"label": "Contacts Without Current Membership", "description": "Current contacts with email who do not match a current paid member."}};
const fallbackBaseUrl = clean(settings.n8n_base_url) || 'http://n8n:5678';
const n8nBaseUrl = deriveBaseUrl(headers, fallbackBaseUrl);
const listKey = Object.prototype.hasOwnProperty.call(listOptions, clean(query.list_key)) ? clean(query.list_key) : '';
const templateKey = clean(query.template_key);
const signatureTemplateKey = clean(query.signature_template_key) || clean(settings.email_signature_template_key) || 'signature';
const returnUrl = clean(query.return_url) || (n8nBaseUrl + '/webhook/member-list-mailout');
const defaultDeliveryMode = clean(settings.email_delivery_mode).toLowerCase() === 'production' ? 'production' : 'test';
const deliveryMode = truthy(query.test_mode) || clean(query.delivery_mode).toLowerCase() === 'test' || defaultDeliveryMode !== 'production' ? 'test' : 'production';
const option = listOptions[listKey] || null;
const errorMessage = !listKey ? 'A valid recipient list is required.' : (!templateKey ? 'template_key is required.' : '');
return [{ json: {
  list_key: listKey,
  list_label: option?.label || '',
  list_description: option?.description || '',
  template_key: templateKey,
  signature_template_key: signatureTemplateKey,
  sender_name: clean(settings.email_sender_name) || 'Steve Short',
  reply_to: clean(settings.email_reply_to) || 'members.avondaleltc@gmail.com',
  delivery_mode: deliveryMode,
  test_recipient: clean(settings.email_test_recipient) || 'steve.short@gmail.com',
  return_url: returnUrl,
  n8n_base_url: n8nBaseUrl,
  error_message: errorMessage
} }];

const input = $('Resolve Preview Request').first()?.json ?? {};
const context = (() => { try { return $('Load Preview Context').first()?.json ?? {}; } catch { return {}; } })();
const message = context.error_message || input.error_message || 'Unable to prepare the preview.';
const returnUrl = input.return_url || '#';
const escapeHtml = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Preview unavailable</title><style>body{margin:0;padding:24px;background:#f4f7fb;font-family:Lato,Arial,sans-serif;color:#1f2937}.panel{max-width:760px;margin:0 auto;background:#fff;border:1px solid #d8e1ec;border-radius:20px;box-shadow:0 18px 40px rgba(15,23,42,.08);padding:28px}h1{margin:0 0 10px;font-size:30px}.message{margin:18px 0;padding:14px 16px;border-radius:14px;background:#fef3f2;color:#b42318;font-weight:700}.button{display:inline-flex;align-items:center;justify-content:center;padding:12px 18px;border-radius:999px;text-decoration:none;font-weight:700;background:linear-gradient(135deg,#0f766e 0%,#115e59 100%);color:#fff}</style></head><body><div class="panel"><h1>Preview Unavailable</h1><p>The member-list mailout preview could not be prepared.</p><div class="message">' + escapeHtml(message) + '</div><a class="button" href="' + escapeHtml(returnUrl) + '">Back to Mailout App</a></div></body></html>';
return [{ json: { html } }];

const input = $('Resolve Preview Request').first()?.json ?? {};
const context = $('Load Preview Context').first()?.json ?? {};
const parseMaybe = (value, fallback) => {
  if (value === null || value === undefined || value === '') return fallback;
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return fallback; }
  }
  return value;
};
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const recipients = Array.isArray(parseMaybe(context.recipients, [])) ? parseMaybe(context.recipients, []) : [];
const recipientSample = Array.isArray(parseMaybe(context.recipient_sample, [])) ? parseMaybe(context.recipient_sample, []) : [];
const imageRows = Array.isArray(parseMaybe(context.image_rows, [])) ? parseMaybe(context.image_rows, []) : [];
const tokenMap = {
  '{{$json.list_name}}': context.list_label ?? '',
  '{{$json.list_label}}': context.list_label ?? '',
  '{{$json.list_key}}': context.list_key ?? '',
  '{{$json.recipient_count}}': String(context.recipient_count ?? 0),
  '{{$json.current_season}}': context.current_season ?? '',
  '{{$json.previous_season}}': context.previous_season ?? '',
  '{{list_name}}': context.list_label ?? '',
  '{{list_label}}': context.list_label ?? '',
  '{{list_key}}': context.list_key ?? '',
  '{{recipient_count}}': String(context.recipient_count ?? 0),
  '{{current_season}}': context.current_season ?? '',
  '{{previous_season}}': context.previous_season ?? ''
};
const applyTokens = (value) => {
  let rendered = String(value ?? '');
  for (const [token, replacement] of Object.entries(tokenMap)) {
    rendered = rendered.split(token).join(String(replacement));
  }
  return rendered.trim();
};
const emailType = clean(context.html_template) ? 'html' : 'text';
const bodySource = emailType === 'html' ? (context.html_template ?? context.text_template ?? '') : (context.text_template ?? context.html_template ?? '');
const signatureSource = emailType === 'html' ? (context.signature_html_template ?? context.signature_text_template ?? '') : (context.signature_text_template ?? context.signature_html_template ?? '');
const renderedBody = applyTokens(bodySource);
const renderedSignature = applyTokens(signatureSource);
return [{ json: {
  list_key: context.list_key,
  list_label: context.list_label,
  list_description: context.list_description,
  recipient_count: Number(context.recipient_count || 0),
  recipients,
  recipient_sample: recipientSample,
  current_season: clean(context.current_season),
  previous_season: clean(context.previous_season),
  template_key: clean(context.template_key || input.template_key),
  template_name: clean(context.template_name || input.template_key),
  signature_template_key: clean(context.signature_template_key || input.signature_template_key),
  delivery_mode: input.delivery_mode,
  test_recipient: input.test_recipient,
  return_url: input.return_url,
  sender_name: input.sender_name,
  reply_to: input.reply_to,
  rendered_subject: applyTokens(context.subject_template ?? 'Message from Avondale Tennis Club'),
  rendered_body: renderedBody,
  rendered_signature: renderedSignature,
  combined_preview_html: emailType === 'html' ? [renderedBody, renderedSignature].filter(Boolean).join('') : '',
  combined_preview_text: [clean(renderedBody), clean(renderedSignature)].filter(Boolean).join('\n\n'),
  email_type: emailType,
  image_rows: imageRows,
  send_url: input.n8n_base_url + '/webhook/send-member-list-email'
} }];

const item = $('Render Preview Data').first()?.json ?? {};
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const escapeHtml = (value) => clean(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const toScript = (value) => JSON.stringify(value ?? null).replace(/<\/script/gi, '<\\/script');
const sampleHtml = (Array.isArray(item.recipient_sample) ? item.recipient_sample : []).map((recipient) => '<li><strong>' + escapeHtml(recipient.recipient_name || recipient.member_name || recipient.recipient_email) + '</strong><span>' + escapeHtml(recipient.recipient_email || '') + '</span></li>').join('');
const modeLabel = item.delivery_mode === 'production' ? 'Production' : 'Test';
const emptySampleHtml = '<p style="margin:0;color:var(--muted);">No recipients available.</p>';
const previewHtml = item.email_type === 'html'
  ? '<div id="rendered-preview" class="preview-box">' + String(item.combined_preview_html || '') + '</div>'
  : '<div id="rendered-preview" class="preview-box preview-text">' + escapeHtml(item.combined_preview_text || '') + '</div>';
const signatureHtml = item.email_type === 'html'
  ? '<div class="preview-box">' + String(item.rendered_signature || '') + '</div>'
  : '<div class="preview-box preview-text">' + escapeHtml(item.rendered_signature || '') + '</div>';
const editorHtml = item.email_type === 'html'
  ? '<div id="message-editor-host" class="editor-host"></div><textarea id="message-editor-input" style="display:none"></textarea>'
  : '<textarea id="message-editor-input" style="min-height:320px"></textarea>';
const html = `<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width, initial-scale=1'>
  <title>Member List Mailout Preview</title>
  <script src='https://cdn.jsdelivr.net/npm/tinymce@7/tinymce.min.js' referrerpolicy='origin'></script>
  <style>
    :root { --bg:#f4f7fb; --panel:#ffffff; --ink:#1f2937; --muted:#64748b; --line:#d8e1ec; --accent:#0f766e; --accent-2:#115e59; --soft:#edfdf9; --warn:#8a5a00; --warn-bg:#fff7db; }
    * { box-sizing:border-box; }
    body { margin:0; background:radial-gradient(circle at top left, #ffffff 0%, #eef5f3 35%, var(--bg) 100%); color:var(--ink); font-family:Lato, 'Helvetica Neue', Arial, sans-serif; }
    .wrap { max-width:1280px; margin:0 auto; padding:24px; display:grid; gap:20px; }
    .hero,.panel { background:var(--panel); border:1px solid var(--line); border-radius:22px; box-shadow:0 20px 45px rgba(15,23,42,.08); }
    .hero { padding:28px 30px; display:flex; justify-content:space-between; gap:18px; flex-wrap:wrap; }
    .hero h1 { margin:0 0 8px; font-size:34px; }
    .hero p { margin:0; color:var(--muted); max-width:780px; line-height:1.6; }
    .badge { display:inline-flex; align-items:center; border-radius:999px; padding:8px 12px; font-size:13px; font-weight:700; background:var(--soft); color:var(--accent-2); }
    .layout { display:grid; gap:20px; grid-template-columns:minmax(0,1.45fr) minmax(320px,.75fr); }
    .panel { padding:22px; }
    .field { display:grid; gap:8px; margin-bottom:18px; }
    .field span { font-size:14px; font-weight:700; }
    input[type='text'], textarea { width:100%; border:1px solid var(--line); border-radius:14px; padding:12px 14px; font:inherit; color:var(--ink); background:#fff; }
    .checkbox { display:inline-flex; align-items:center; gap:10px; font-weight:600; }
    .checkbox input { width:18px; height:18px; }
    .button { display:inline-flex; align-items:center; justify-content:center; border:0; border-radius:999px; padding:12px 18px; font:inherit; font-weight:700; cursor:pointer; text-decoration:none; color:#fff; background:linear-gradient(135deg, var(--accent) 0%, var(--accent-2) 100%); box-shadow:0 10px 25px rgba(15,118,110,.22); }
    .button-soft { background:#eef2f6; color:var(--ink); box-shadow:none; border:1px solid var(--line); }
    .compose { display:grid; gap:18px; }
    .editor-shell { border:1px solid var(--line); border-radius:18px; overflow:hidden; background:#fff; }
    .editor-host { min-height:320px; padding:16px; }
    .preview-box { border:1px solid var(--line); border-radius:18px; background:linear-gradient(180deg,#fff 0%,#f8fbff 100%); padding:18px; min-height:220px; }
    .preview-box table { width:100%; border-collapse:collapse; }
    .preview-box th,.preview-box td { border:1px solid #d9e2ec; padding:8px; }
    .preview-text { white-space:pre-wrap; font-family:ui-monospace, SFMono-Regular, Menlo, monospace; font-size:14px; line-height:1.6; }
    .stack { display:grid; gap:16px; }
    .meta-list { display:grid; gap:10px; }
    .meta-list div { display:grid; gap:4px; }
    .meta-label { font-size:12px; text-transform:uppercase; letter-spacing:.08em; color:var(--muted); font-weight:700; }
    .sample-list { list-style:none; padding:0; margin:0; display:grid; gap:12px; }
    .sample-list li { border:1px solid var(--line); border-radius:14px; padding:12px 14px; background:#fbfcfe; display:grid; gap:4px; }
    .sample-list span { color:var(--muted); font-size:13px; word-break:break-all; }
    .callout { border:1px solid #f1dfb0; background:var(--warn-bg); color:var(--warn); border-radius:16px; padding:14px 16px; line-height:1.6; }
    .tox-tinymce-inline { border:0 !important; }
    .tox-editor-header { box-shadow:none !important; border-bottom:1px solid var(--line) !important; }
    @media (max-width: 980px) { .layout { grid-template-columns:1fr; } }
    @media (max-width: 720px) { .wrap { padding:14px; } .hero,.panel { padding:18px; } .hero h1 { font-size:28px; } }
  </style>
</head>
<body>
  <div class='wrap'>
    <section class='hero'>
      <div>
        <h1>Member List Mailout Preview</h1>
        <p>Review the rendered shared message, edit the final body, and send it through the shared Gmail transport. Production sends use the club address in <strong>To</strong> and place the resolved cohort in <strong>BCC</strong>.</p>
      </div>
      <div class='badge'>${escapeHtml(modeLabel)} mode</div>
    </section>
    <section class='layout'>
      <div class='panel'>
        <form id='compose-form' class='compose' method='POST' action='${escapeHtml(item.send_url || '#')}'>
          <input type='hidden' name='list_key' value='${escapeHtml(item.list_key)}'>
          <input type='hidden' name='template_key' value='${escapeHtml(item.template_key)}'>
          <input type='hidden' name='signature_template_key' value='${escapeHtml(item.signature_template_key)}'>
          <input type='hidden' name='return_url' value='${escapeHtml(item.return_url)}'>
          <input type='hidden' name='email_type' value='${escapeHtml(item.email_type)}'>
          <textarea id='rendered-message-output' name='rendered_message' style='display:none'></textarea>
          <textarea id='rendered-signature-output' name='rendered_signature' style='display:none'>${escapeHtml(item.rendered_signature || '')}</textarea>
          <label class='field'>
            <span>Subject</span>
            <input type='text' name='rendered_subject' value='${escapeHtml(item.rendered_subject)}' required>
          </label>
          <section class='field'>
            <span>Message</span>
            <div class='editor-shell'>
              <div id='message-toolbar'></div>
              ${editorHtml}
            </div>
          </section>
          <div class='callout'>List tokens available in templates: <code>{{$json.list_name}}</code>, <code>{{$json.recipient_count}}</code>, <code>{{$json.current_season}}</code>, <code>{{$json.previous_season}}</code>.</div>
          <div style='display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap;'>
            <label class='checkbox'><input type='checkbox' name='test_mode' value='1'${item.delivery_mode === 'production' ? '' : ' checked'}><span>Send in test mode</span></label>
            <div style='display:flex;gap:12px;flex-wrap:wrap;'>
              <a class='button button-soft' href='${escapeHtml(item.return_url)}'>Back to Mailout App</a>
              <button class='button' type='submit'>Send Mailout</button>
            </div>
          </div>
        </form>
      </div>
      <aside class='stack'>
        <section class='panel'>
          <div class='meta-list'>
            <div><span class='meta-label'>Recipient List</span><strong>${escapeHtml(item.list_label)}</strong></div>
            <div><span class='meta-label'>Resolved Recipients</span><strong>${escapeHtml(String(item.recipient_count || 0))}</strong></div>
            <div><span class='meta-label'>Template</span><strong>${escapeHtml(item.template_name || item.template_key)}</strong></div>
            <div><span class='meta-label'>Visible Club Address</span><strong>${escapeHtml(item.reply_to || '')}</strong></div>
            <div><span class='meta-label'>Test Recipient</span><strong>${escapeHtml(item.test_recipient || '')}</strong></div>
          </div>
          <p style='margin:14px 0 0;color:var(--muted);line-height:1.6;'>${escapeHtml(item.list_description || '')}</p>
        </section>
        <section class='panel'>
          <h2 style='margin:0 0 12px;font-size:19px;'>Recipient Sample</h2>
          ${sampleHtml ? `<ul class='sample-list'>${sampleHtml}</ul>` : emptySampleHtml}
        </section>
        <section class='panel'>
          <h2 style='margin:0 0 12px;font-size:19px;'>Signature Preview</h2>
          ${signatureHtml}
        </section>
        <section class='panel'>
          <h2 style='margin:0 0 12px;font-size:19px;'>Rendered Preview</h2>
          ${previewHtml}
        </section>
      </aside>
    </section>
  </div>
  <script>
    (function() {
      var item = ${toScript(item)};
      var emailType = String(item.email_type || 'text');
      var form = document.getElementById('compose-form');
      var host = document.getElementById('message-editor-host');
      var input = document.getElementById('message-editor-input');
      var output = document.getElementById('rendered-message-output');
      var preview = document.getElementById('rendered-preview');
      var initialBody = String(item.rendered_body || '');
      var signature = String(item.rendered_signature || '');
      var normalizeHtml = function(value) { return String(value || '').replace(/<!doctype[^>]*>/ig, '').replace(/<\/?(?:html|body)[^>]*>/ig, '').trim(); };
      var getValue = function() {
        if (emailType === 'html') {
          var editor = window.tinymce ? window.tinymce.get('member-list-mailout-editor') : null;
          if (editor) return editor.getContent({ format: 'html' });
          return host ? host.innerHTML : '';
        }
        return input ? String(input.value || '') : '';
      };
      var syncPreview = function() {
        var message = getValue();
        if (!preview) return;
        if (emailType === 'html') {
          preview.innerHTML = normalizeHtml(String(message || '') + String(signature || ''));
        } else {
          preview.textContent = [String(message || '').trim(), String(signature || '').trim()].filter(Boolean).join('\n\n');
        }
      };
      var syncSubmit = function() {
        var message = getValue();
        output.value = emailType === 'html' ? normalizeHtml(message) : String(message || '').trim();
      };
      if (emailType === 'html' && host) {
        host.id = 'member-list-mailout-editor';
        host.innerHTML = normalizeHtml(initialBody);
        window.tinymce.init({
          target: host,
          inline: true,
          fixed_toolbar_container: '#message-toolbar',
          promotion: false,
          branding: false,
          menubar: false,
          plugins: 'autolink advlist lists link table code',
          toolbar: 'undo redo | blocks | bold italic underline | bullist numlist | link table | removeformat code',
          toolbar_mode: 'wrap',
          content_style: 'body { font-family: Helvetica, Arial, sans-serif; font-size: 14px; line-height: 1.5; }',
          setup: function(editor) {
            editor.on('init change input undo redo SetContent keyup NodeChange', function() { syncPreview(); });
          }
        }).catch(function() { syncPreview(); });
      } else if (input) {
        input.value = initialBody;
        ['input', 'keyup', 'change', 'paste', 'blur'].forEach(function(eventName) {
          input.addEventListener(eventName, syncPreview);
        });
      }
      syncPreview();
      form.addEventListener('submit', function() { syncSubmit(); });
    })();
  </script>
</body>
</html>`;
return [{ json: { html } }];
